<script setup>
import { ref,computed } from 'vue'
import { router } from '../router.js'
import { state,t } from '../state.js'
import { person,introDraft,socialAction } from '../social-state.js'
import { characterCount } from '../domain/content.js'
import AppModal from './AppModal.vue'
import ActionButton from './ActionButton.vue'
const props=defineProps({peerId:String,from:String,icon:Boolean,profileMode:Boolean})
const open=ref(false),p=computed(()=>person(props.peerId)),relation=computed(()=>p.value?.relationship),draft=computed(()=>introDraft(props.peerId))
const actionLabel=computed(()=>props.profileMode?(relation.value?.canMessage?'s.openChat':relation.value?.connection?(relation.value.connection.status==='declined'?'s.connectionRejected':'s.pending'):'s.profileChatAvailability'):relation.value?.canMessage?'s.openChat':relation.value?.connection?.status==='declined'?'s.connectionRejected':relation.value?.connection?'s.pending':relation.value?.request?(relation.value.request.status==='ignored'?'s.ignored':'s.pending'):'s.request')
async function activate(){if((relation.value?.canMessage||relation.value?.connection&&(!props.profileMode||relation.value.connection.direction==='received'&&relation.value.connection.status==='pending'))&&!relation.value.blocked){if(await socialAction('thread',{peerId:props.peerId},{notice:''})){const previous=router.currentRoute.value.query.from;if(router.currentRoute.value.name==='profile'&&typeof previous==='string'&&previous.split('?')[0]==='/conversation/'+encodeURIComponent(props.peerId))router.replace(previous);else router.push({name:'conversation',params:{peer:props.peerId},query:{from:props.from||'/chats'}})}}else open.value=true}
async function send(){if(await socialAction('request',{peerId:props.peerId,...draft.value},{notice:'s.requestSaved'}))open.value=false}
</script>
<template><button :class="icon?'profile-chat-action':'action-button purple-gradient'" :aria-label="t(actionLabel)" :disabled="!!state.ui.busy" @click="activate"><img v-if="icon" :src="relation?.canMessage?'/images/profile/following-chat.png':'/images/profile/follow-chat.png'" alt=""/><span v-else>{{ t(actionLabel) }}</span></button><AppModal v-if="open" :title="t('s.intro')" :closable="!state.ui.busy" @close="open=false"><template v-if="relation?.blocked"><p>{{ t('s.blocked') }}</p></template><template v-else-if="profileMode"><p>{{ t(relation?.connection?.status==='declined'?'s.connectionDeclined':relation?.connection?'s.connectionWaiting':'s.profileContactRule') }}</p></template><template v-else-if="relation?.request"><p>{{ t(relation.request.status==='ignored'?'s.noResend':'s.waiting') }}</p><ActionButton v-if="relation.request.direction==='received'&&relation.request.status==='pending'" @click="open=false;router.push('/friend-requests')">{{ t('s.requests') }}</ActionButton></template><template v-else><p class="sheet-hint">{{ t('s.introHint') }}</p><label class="sheet-input-label">{{ t('s.introPlaceholder') }}<textarea v-model="draft.body" :disabled="!!state.ui.busy"/></label><p class="field-hint">{{ characterCount(draft.body) }} / 500</p><p v-if="state.ui.error" class="error-banner" role="alert" :data-error-code="state.ui.error">{{ t('errors.'+state.ui.error) }}</p></template><template v-if="!profileMode&&!relation?.blocked&&!relation?.request" #footer><ActionButton class="purple-gradient" :busy="!!state.ui.busy" :disabled="!draft.body.trim()||characterCount(draft.body)>500" @click="send">{{ t('s.sendRequest') }}</ActionButton></template></AppModal></template>
